package org.springframework.samples.petclinic.rest.error;

/**
 * Thrown when an owner is created whose last name and address match those of an existing owner
 * (compared case-insensitively and with collapsed whitespace) without the request opting in to a
 * shared household. Carries the conflicting values so the REST layer can report what was rejected.
 */
public class DuplicateHouseholdException extends RuntimeException {

    private final String lastName;

    private final String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with last name '" + lastName + "' at address '" + address + "' already exists");
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}

